"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["95775"],{69142(e,t,a){a.r(t),a.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>p,contentTitle:()=>o,toc:()=>h,assets:()=>d});var i=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-v2-participant-update","title":"Submit the participant certificate and bridge update (v2)","description":"Stages a change to a participant encryption certificate and/or endpoint URL; returns a transactionid for passcode confirmation via /update/validate.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-update.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-v2-participant-update","permalink":"/docs/pr-15/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-update","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Submit the participant certificate and bridge update (v2)","sidebar_label":"Submit the participant certificate and bridge update (v2)","sidebar_class_name":"api-method api-method--post","description":"Stages a change to a participant encryption certificate and/or endpoint URL; returns a transactionid for passcode confirmation via /update/validate.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Submit the participant update (v1)","permalink":"/docs/pr-15/docs/nhcx/v1/api/registry/endpoints/registry-participant-update"},"next":{"title":"Submit the participant search","permalink":"/docs/pr-15/docs/nhcx/v1/api/registry/endpoints/registry-participant-search"}}'),n=a(62540),r=a(43023),s=a(75064),c=JSON.parse('{"id":"registry_v2_participant_update","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/v2/participant/update","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Participant certificate and bridge update (v2)","title":"Submit the participant certificate and bridge update (v2)","description":"Stages a change to a participant encryption certificate and/or endpoint URL; returns a transactionid for passcode confirmation via /update/validate.\\n\\n### Business purpose\\n\\nExactly two operational values rotate over a participant\'s life: the public encryption certificate that counterparties encrypt claims data with, and the endpoint (bridge) URL that the gateway delivers callbacks to. Both are security-sensitive, so the v2 update takes only those fields and gates the change behind an SMS passcode to the registered mobile number. It is step 3 of the production onboarding sequence, where a newly confirmed participant publishes its certificate for the first time, and the documented route for annual key rotation thereafter.\\n\\n### When to use\\n\\nUse it immediately after creation confirmation (/validate) to upload encryptioncert and endpointurl, and again whenever either value changes; always follow with GET /update/validate within 24 hours. The production URL is https://apisprod.NHA.gov.in/pmjay/hcx/participanthcxservice/v2/participant/update. If only the certificate changes and passcode validation is not wanted, /v2/update/cert is the documented alternative. This is a synchronous JSON registry call with no workflow or x-hcx-status codes.\\n\\n### Preconditions\\n\\n- participantcode is a valid code already registered in NHCX and its creation confirmation has been completed.\\n- The certificate (public key) is Base64-encoded; the update validation explicitly requires this.\\n- Bearer token in bearer_auth with the Bearer prefix, Accept and Content-Type: application/json.\\n- ParticipantCertUpdateRequest: participantcode required; encryptioncert and endpointurl optional (the base URL).\\n- The new private key is already deployed on the callback host so decryption works the moment the change goes live.\\n\\n### Postconditions\\n\\nHTTP 200 with ParticipantCertUpdateResp: participant_code, status and transactionid. A passcode is sent to the registered mobile number; the pair is valid for 24 hours and each new trigger replaces it. The change is not live until GET /update/validate succeeds, after which /fetch/certs returns the new certificate and callbacks go to the new endpoint. Counterparties may serve a cached copy for up to 24 hours. Errors use the 400/404/500 ErrorResponse envelope.\\n\\n### Common mistakes\\n\\n- Calling it before creation has been confirmed with /validate; the validations require a confirmed participant code.\\n- Sending the raw PEM instead of the Base64-encoded certificate.\\n- Using v1 field names (participant_code, encryption_cert, endpoint_URL) in this flattened lowercase body.\\n- Treating the 200 as completion and skipping /update/validate, so the old certificate stays live.\\n- Re-triggering the update while a passcode is pending, invalidating the earlier transaction ID.\\n- Losing the transaction ID, which forces the update to be issued again.\\n\\n### Best practices\\n\\n- Prepare the new key pair, deploy the PKCS8 private key to the callback host and only then publish the certificate.\\n- Keep the previous private key available for at least 24 hours after validation to decrypt callbacks encrypted against a cached certificate.\\n- Persist transactionid with its 24-hour expiry and complete /update/validate promptly.\\n- Rotate encryption keys once a year, matching the 365-day validity of the self-signed certificate.\\n- Verify the new endpointurl is a domain name on an India-based server with the NHCX NAT IPs whitelisted before submitting.\\n\\n### Related scenario\\n\\nA TPA has just confirmed its production participant with /validate. Its engineers generate a 2048-bit RSA key, a 365-day self-signed X.509 certificate, Base64-encode it and deploy the private key to the callback host. They call /v2/participant/update with participantcode, encryptioncert and endpointurl; the response returns status and a transactionid, and the registered phone receives a passcode. After GET /update/validate succeeds, the first provider to call /fetch/certs for the TPA receives the new certificate and can encrypt a pre-authorisation for it.\\n\\n### Specification\\n\\nChapter [Your certificate](/docs/nhcx/v1/getting-started/your-certificate) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"participantcode","type":"string","required":false,"description":"","encrypted":false},{"name":"encryptioncert","type":"string","required":false,"description":"","encrypted":false},{"name":"endpointurl","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"participantcode":"XXXXX7583@hcx","encryptioncert":"LS0tLS1CRUdJTiBDRVJUSUZJQ0FURS0tLS0t...","endpointurl":"https://nhcx.demotpa.example.in"},"responses":[{"status":"200","description":"HTTP 200 with ParticipantCertUpdateResp: participant_code, status and transactionid.","example":{"participant_code":"XXXXX7583@hcx","status":"Update initiated","transactionid":"1vouv8tlz2tnl-1fpspjhwj07c6"}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/update \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participantcode\\": \\"XXXXX7583@hcx\\",\\n  \\"encryptioncert\\": \\"LS0tLS1CRUdJTiBDRVJUSUZJQ0FURS0tLS0t...\\",\\n  \\"endpointurl\\": \\"https://nhcx.demotpa.example.in\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/update \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participantcode\\": \\"XXXXX7583@hcx\\",\\n  \\"encryptioncert\\": \\"LS0tLS1CRUdJTiBDRVJUSUZJQ0FURS0tLS0t...\\",\\n  \\"endpointurl\\": \\"https://nhcx.demotpa.example.in\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/update\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"participantcode\\": \\"XXXXX7583@hcx\\",\\n        \\"encryptioncert\\": \\"LS0tLS1CRUdJTiBDRVJUSUZJQ0FURS0tLS0t...\\",\\n        \\"endpointurl\\": \\"https://nhcx.demotpa.example.in\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/update\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"participantcode\\": \\"XXXXX7583@hcx\\",\\n    \\"encryptioncert\\": \\"LS0tLS1CRUdJTiBDRVJUSUZJQ0FURS0tLS0t...\\",\\n    \\"endpointurl\\": \\"https://nhcx.demotpa.example.in\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let p={title:"Submit the participant certificate and bridge update (v2)",sidebar_label:"Submit the participant certificate and bridge update (v2)",sidebar_class_name:"api-method api-method--post",description:"Stages a change to a participant encryption certificate and/or endpoint URL; returns a transactionid for passcode confirmation via /update/validate.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},o,d={},h=[];function l(e){return(0,n.jsx)(s.A,{operation:c})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}}}]);